  function tx(t,px,py,font,col,al){x.font=font;x.fillStyle=col;x.textAlign=al||'right';x.fillText(t,px,py)}
  function wrapT(t,maxW,font){x.font=font;var ws=String(t).split(/\s+/),ls=[],c='';ws.forEach(function(w){var tt=c?c+' '+w:w;if(x.measureText(tt).width>maxW&&c){ls.push(c);c=w}else c=tt});if(c)ls.push(c);return ls}
  x.fillStyle='#fff';x.fillRect(0,0,W,H);x.fillStyle=G;x.fillRect(0,0,W,16);
  x.fillStyle='rgba(41,146,112,.05)';x.beginPath();x.arc(W-60,320,380,0,Math.PI*2);x.fill();
