    rows.forEach(function(r,i){var yy=cy+104+i*52;tx(r[0],cx+cw-28,yy,'400 22px '+TXT,MUT,'right');if(r[2])x.direction='ltr';tx(fit(String(r[1]),300,'600 23px '+(r[2]?NUM:TXT)),cx+28,yy,'600 23px '+(r[2]?NUM:TXT),INK,'left');x.direction='rtl'});
