function compress(file,maxSide,maxB){return new Promise(function(ok,no){var fr=new FileReader();fr.onload=function(){var im=new Image();im.onload=function(){var s=Math.min(1,maxSide/Math.max(im.width,im.height)),w=Math.round(im.width*s),hh=Math.round(im.height*s),cv=document.createElement('canvas');cv.width=w;cv.height=hh;cv.getContext('2d').drawImage(im,0,0,w,hh);var q=.8,u=cv.toDataURL('image/jpeg',q);while(u.length>maxB*1.37&&q>.36){q-=.1;u=cv.toDataURL('image/jpeg',q)}ok(u)};im.onerror=function(){no(new Error('bad'))};im.src=fr.result};fr.onerror=function(){no(new Error('read'))};fr.readAsDataURL(file)})}
